ALTER TABLE leads ADD COLUMN IF NOT EXISTS sales_status text NOT NULL DEFAULT 'new';
ALTER TABLE leads ADD COLUMN IF NOT EXISTS sales_note text NOT NULL DEFAULT '';
ALTER TABLE leads ADD COLUMN IF NOT EXISTS follow_up_at timestamptz;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE leads ADD COLUMN IF NOT EXISTS attribution jsonb NOT NULL DEFAULT '{}';
ALTER TABLE leads ADD COLUMN IF NOT EXISTS submission_id uuid;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS notify_key uuid NOT NULL DEFAULT gen_random_uuid();
ALTER TABLE leads ADD COLUMN IF NOT EXISTS notify_attempts integer NOT NULL DEFAULT 0;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS notify_after timestamptz NOT NULL DEFAULT now();
ALTER TABLE leads ADD COLUMN IF NOT EXISTS notify_locked_until timestamptz;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS notify_error text;
ALTER TABLE leads ADD COLUMN IF NOT EXISTS notify_started_at timestamptz;
CREATE UNIQUE INDEX IF NOT EXISTS leads_submission_id_idx ON leads(submission_id);
CREATE INDEX IF NOT EXISTS leads_follow_up_idx ON leads(follow_up_at) WHERE sales_status NOT IN ('won','lost');
CREATE TABLE IF NOT EXISTS lead_history (id bigserial PRIMARY KEY, lead_id bigint NOT NULL REFERENCES leads(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), actor text NOT NULL, status text NOT NULL, note text NOT NULL, follow_up_at timestamptz);
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY, hits integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS contact_events (id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), event text NOT NULL, path text NOT NULL, source text NOT NULL DEFAULT '', medium text NOT NULL DEFAULT '', campaign text NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS contact_events_date_idx ON contact_events(created_at);
CREATE TABLE IF NOT EXISTS system_state (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS document_files (id uuid PRIMARY KEY,title text NOT NULL,kind text NOT NULL,pathname text NOT NULL,size integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
